args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?mother ?motherLabel (COALESCE(?deathDate, ?deathDate2, ?deathDate3, ?deathDate4) AS ?death) WHERE {
  BIND(dbr:Matilda_of_Boulogne,_Duchess_of_Brabant AS ?matilda)
  ?matilda dbo:mother ?mother .
  OPTIONAL { ?mother dbo:deathDate ?deathDate. }
  OPTIONAL { ?mother dbp:deathDate ?deathDate2. }
  OPTIONAL { ?mother dbp:death_date ?deathDate3. }
  OPTIONAL { ?mother dbp:death ?deathDate4. }
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = "en") }
}

